-- The 2025-26 Grade 11 KTP, kept as the Grade 11 plan of the students who are
-- now in Grade 12 (generated by scripts/build_ktp_cohort.py). It reuses the
-- topics already on the site; nothing happens where the programme is missing.
do $$
declare v uuid; g uuid; t uuid; u uuid;
begin
  select id into v from public.curriculum_versions where code = 'NIS_CS_2026_2027';
  if v is null then return; end if;
  delete from public.grades where curriculum_version_id = v and number = 11 and for_student_grade = 12;
    values (v, 11, 'Grade 11 · KTP 2025–26', 210, 5, 12) returning id into g;
RAM and ROM on wikibooks Machine Level Architecture', 2 from public.topics where curriculum_version_id = v and slug = 'paper-cpu-memory-and-peripherals';
https://habr.com/post/111674/ What does SDLC stand for?', 0 from public.topics where curriculum_version_id = v and slug = 'g11-sdlc-models';
How to Upload Android Apps to Google Play https://www.youtube.com/watch?v=GCmXjdp--HM How to Release an iOS App to the App Store', 1 from public.topics where curriculum_version_id = v and slug = 'paper-mobile-application-development';
end $$;

